-- 005 - Equipment: tractors, machinery and implements, with warranty and service tracking
-- (generated by scripts/generate-sql.js - do not edit by hand).
-- Run after 001-004. Safe to run more than once. Uses set_updated_at() and can_write_farm()
-- from 002. Deleting a piece of equipment also deletes its service log.
-- Until this is run the app still works; the Equipment pages just stay empty.

-- equipment
create table if not exists public.equipment (
  id uuid primary key default gen_random_uuid(),
  farm_id uuid not null references public.farms (id) on delete cascade,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  name text not null,
  category text not null,
  make text not null default '',
  model text not null default '',
  serial_number text not null default '',
  purchase_date date,
  purchase_cost numeric,
  supplier text not null default '',
  status text not null,
  location text not null default '',
  hours_meter numeric,
  warranty_expiry date,
  warranty_notes text not null default '',
  notes text not null default '',
  extra jsonb not null default '{}'::jsonb check (jsonb_typeof(extra) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint equipment_farm_id_id_key unique (farm_id, id),
  constraint equipment_purchase_cost_min check (purchase_cost >= 0),
  constraint equipment_hours_meter_min check (hours_meter >= 0)
);
create index if not exists equipment_farm_created_idx on public.equipment (farm_id, created_at desc);
drop trigger if exists set_updated_at on public.equipment;
create trigger set_updated_at before update on public.equipment
  for each row execute function public.set_updated_at();
alter table public.equipment enable row level security;
revoke all on public.equipment from anon, public;
grant select, insert, update, delete on public.equipment to authenticated;
drop policy if exists "Farm members can view equipment" on public.equipment;
create policy "Farm members can view equipment"
  on public.equipment for select to authenticated
  using (public.is_farm_member(farm_id));
drop policy if exists "Farm editors can insert equipment" on public.equipment;
create policy "Farm editors can insert equipment"
  on public.equipment for insert to authenticated
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can update equipment" on public.equipment;
create policy "Farm editors can update equipment"
  on public.equipment for update to authenticated
  using (public.can_write_farm(farm_id))
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can delete equipment" on public.equipment;
create policy "Farm editors can delete equipment"
  on public.equipment for delete to authenticated
  using (public.can_write_farm(farm_id));

-- equipment-services
create table if not exists public.equipment_services (
  id uuid primary key default gen_random_uuid(),
  farm_id uuid not null references public.farms (id) on delete cascade,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  equipment_id uuid not null,
  service_type text not null,
  status text not null,
  service_date date not null,
  hours_at_service numeric,
  cost numeric,
  performed_by text not null default '',
  next_service_date date,
  next_service_hours numeric,
  notes text not null default '',
  extra jsonb not null default '{}'::jsonb check (jsonb_typeof(extra) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint equipment_services_farm_id_id_key unique (farm_id, id),
  constraint equipment_services_equipment_id_fkey foreign key (farm_id, equipment_id) references public.equipment (farm_id, id) on delete cascade,
  constraint equipment_services_hours_at_service_min check (hours_at_service >= 0),
  constraint equipment_services_cost_min check (cost >= 0),
  constraint equipment_services_next_service_hours_min check (next_service_hours >= 0)
);
create index if not exists equipment_services_farm_created_idx on public.equipment_services (farm_id, created_at desc);
create index if not exists equipment_services_equipment_id_idx on public.equipment_services (farm_id, equipment_id);
drop trigger if exists set_updated_at on public.equipment_services;
create trigger set_updated_at before update on public.equipment_services
  for each row execute function public.set_updated_at();
alter table public.equipment_services enable row level security;
revoke all on public.equipment_services from anon, public;
grant select, insert, update, delete on public.equipment_services to authenticated;
drop policy if exists "Farm members can view equipment_services" on public.equipment_services;
create policy "Farm members can view equipment_services"
  on public.equipment_services for select to authenticated
  using (public.is_farm_member(farm_id));
drop policy if exists "Farm editors can insert equipment_services" on public.equipment_services;
create policy "Farm editors can insert equipment_services"
  on public.equipment_services for insert to authenticated
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can update equipment_services" on public.equipment_services;
create policy "Farm editors can update equipment_services"
  on public.equipment_services for update to authenticated
  using (public.can_write_farm(farm_id))
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can delete equipment_services" on public.equipment_services;
create policy "Farm editors can delete equipment_services"
  on public.equipment_services for delete to authenticated
  using (public.can_write_farm(farm_id));
